//! One module per binding, each answering the files it writes.

pub mod c;
pub mod lua;
pub mod markdown;
pub mod node;
pub mod odin;
pub mod rust;

/// What every generated file opens with.
pub(crate) fn banner(comment: &str, schema: &crate::Schema) -> String {
    format!(
        "{comment} Generated by kui-addon-schema from {}'s schema.lua (ADR 0066); do not edit.\n",
        schema.addon
    )
}
